import logging
import time
from abc import ABC, abstractmethod
from enum import Enum
from typing import NamedTuple

from taf.hw.pdu.device_status import DeviceStatus


class PDU(ABC):
    """PDU is a class providing an Abstract Base Class for all PDU types"""

    def __init__(self, host: str) -> None:
        self._host = host

    @abstractmethod
    def _set_port_status(self, port, status):
        """Set PDU port status"""

    @abstractmethod
    def get_port_status(self, port):
        """Get PDU port status"""

    @property
    @abstractmethod
    def _port_setting(self):
        """Dictionary of settings used to get PDU status/value"""

    @property
    def _reversed_port_settings(self):
        return dict(reversed(i) for i in self._port_setting.items())

    def power_on(self, port):
        return self._set_port_status(port, DeviceStatus.ON)

    def power_off(self, port):
        return self._set_port_status(port, DeviceStatus.OFF)

    def reset(self, ports, time_interval):
        self._set_status_off(ports)
        time.sleep(time_interval)
        self._set_status_on(ports)

    def _set_status_off(self, ports):
        for port in ports:
            self.power_off(port=port)

    def _set_status_on(self, ports):
        for port in ports:
            self.power_on(port=port)

    def set_voltage(self, port, voltage):
        msg = "Given PDU does not support setting the voltage"
        raise NotImplementedError(msg)

    def teardown(self):
        """
        Perform device-specific actions for a PDU if necessary, e.g., close all connections, etc.
        """
        logging.info("No teardown operations defined for this PDU")

    def get_voltage(self, port):
        msg = "Operation not supported for this PDU"
        raise NotImplementedError(msg)

    def get_current(self, port):
        msg = "Operation not supported for this PDU"
        raise NotImplementedError(msg)

    def get_energy_consumption(self, port):
        msg = "Operation not supported for this PDU"
        raise NotImplementedError(msg)

    def get_pdu_info(self) -> "PduIdentInfo":
        """Default identity information for a PDU device.

        Devices should override when they can return a meaningful identifier
        (e.g., SCPI-capable devices via `*IDN?`).
        """
        return PduIdentInfo(identifier="UNKNOWN", identification_type=PduIdentificationType.NOT_IMPLEMENTED)


class PduIdentificationType(Enum):
    NOT_IMPLEMENTED = "NOT_IMPLEMENTED"
    SCPI_IDN = "SCPI_IDN"


class PduIdentInfo(NamedTuple):
    identifier: str
    identification_type: PduIdentificationType
